import {stations,directions,latestViews,nextDirection,resolveStationId,stationChangeNotice} from './space-domain.js?v=base-upload-20261111';
export function mountSimpleTour(records,ecologyStations=[]){
 const tourStations=[...stations,...ecologyStations];
 const panel=document.querySelector('#simple-view');panel.innerHTML='<label>實景站點<select id="simple-station"></select></label><p id="simple-progress" role="status"></p><div class="simple-frame" tabindex="0" aria-label="四向照片導覽，可左右滑動或按方向鍵"><img id="simple-photo" alt="" hidden><p id="simple-empty"></p></div><div id="simple-directions" class="simple-directions"></div><p><button id="turn-left">← 向左看</button> <button id="turn-right">向右看 →</button></p><p><button id="simple-previous">上一站</button> <button id="simple-next">下一站</button> <a id="simple-capture" class="button">拍攝本站照片（管理員）</a></p><p>手機橫放，左右滑動或按方向切換實景。四張普通照片分方向展示，不含天空；尚未發布的方向會保留空位，不會自動補畫。</p>';
 const $=s=>panel.querySelector(s);let kind='north',photoVersion=0,startX;const originalRequested=new URLSearchParams(location.search).get('station'),requested=resolveStationId(originalRequested)||originalRequested;
 const notice=stationChangeNotice(originalRequested);if(notice){const p=document.createElement('p');p.setAttribute('role','status');p.textContent=notice;panel.prepend(p);}
 for(const s of tourStations){const o=document.createElement('option');o.value=s.id;const n=Object.keys(latestViews(records,s.id)).length;o.textContent=`${s.id} ${s.name} · ${n}/4 方向`;$('#simple-station').append(o);}
 $('#simple-station').value=tourStations.some(s=>s.id===requested)?requested:(tourStations.find(s=>Object.keys(latestViews(records,s.id)).length)?.id||'P01');
 for(const [value,label] of directions){const b=document.createElement('button');b.textContent=label;b.dataset.kind=value;b.onclick=()=>{kind=value;render();};$('#simple-directions').append(b);}
 function render(){const station=tourStations.find(s=>s.id===$('#simple-station').value),views=latestViews(records,station.id),photo=views[kind],version=++photoVersion,image=$('#simple-photo');$('#simple-progress').textContent=`${station.id} ${station.name}｜${directions.find(([k])=>k===kind)[1]}｜已發布 ${Object.keys(views).length}/4 方向`;image.hidden=true;image.onload=()=>{if(version===photoVersion){image.hidden=false;$('#simple-empty').hidden=true;}};image.onerror=()=>{if(version===photoVersion){image.hidden=true;$('#simple-empty').hidden=false;$('#simple-empty').textContent='此照片暫時載入失敗，可切換方向或重新整理。';}};$('#simple-empty').hidden=false;$('#simple-empty').textContent=photo?'載入實景照片中…':'本站這個方向尚未發布照片。管理員可先定位、確認站點，再拍攝四個水平方向。';if(photo){image.alt=`${station.name} ${directions.find(([k])=>k===kind)[1]} 現場照片`;image.src=photo.url;}else image.removeAttribute('src');for(const b of $('#simple-directions').children)b.setAttribute('aria-pressed',String(b.dataset.kind===kind));const href=(station.id.startsWith('EC')?'./field.html?eco='+station.id:`./field.html?mode=space&station=${station.id}`);$('#simple-capture').href=href;document.querySelector('#capture-space').href=href;}
 function turn(step){kind=nextDirection(kind,step);render();}
 function stepStation(step){const i=tourStations.findIndex(s=>s.id===$('#simple-station').value);$('#simple-station').value=tourStations[(i+step+tourStations.length)%tourStations.length].id;kind='north';render();}
 $('#simple-station').onchange=()=>{kind='north';render();};$('#turn-left').onclick=()=>turn(-1);$('#turn-right').onclick=()=>turn(1);$('#simple-previous').onclick=()=>stepStation(-1);$('#simple-next').onclick=()=>stepStation(1);
 const frame=$('.simple-frame');frame.addEventListener('pointerdown',e=>{startX=e.clientX;});frame.addEventListener('pointerup',e=>{if(startX!==undefined&&Math.abs(e.clientX-startX)>40)turn(e.clientX<startX?1:-1);startX=undefined;});frame.addEventListener('pointercancel',()=>startX=undefined);frame.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();turn(e.key==='ArrowLeft'?-1:1);}});render();return {reset:()=>{kind='north';render();}};
}
